INSERT INTO news
  (id, status, published_at, title, body, category, related_url, thumbnail_path, updated_at)
VALUES
  ('news-097', '公開', '2026-12-02', 'インフルエンザ予防接種について', '今年もインフルエンザの予防接種を開始いたしました。予約制となっておりますので、お電話または受付にてご予約をお願いいたします。例年、予約が集中しやすいため、早めのご予約をおすすめいたします。', '健診・予防接種', NULL, NULL, '2026-12-02 00:00:00'),
  ('news-096', '公開', '2026-12-01', '年末年始の休診について', '年末年始の休診日は、12月29日（金）〜1月4日（木）となります。年始は1月5日（金）より通常診療を再開いたします。皆様にはご不便をおかけしますが、何卒ご了承くださいますようお願いいたします。', '休診情報', NULL, NULL, '2026-12-01 00:00:00'),
  ('news-095', '公開', '2026-01-08', '健康診断のご案内', '今年も健康診断を実施しております。定期的な健康チェックは、病気の早期発見・予防にとても重要です。各種健康診断メニューをご用意しておりますので、ご希望の方はお電話にてお申し込みください。', '健診・予防接種', NULL, NULL, '2026-01-08 00:00:00'),
  ('news-094', '公開', '2025-04-03', '新型コロナウイルス対策について', '当院では引き続き、新型コロナウイルス感染症対策を徹底しております。ご来院の際には、マスクの着用、手指消毒にご協力をお願いいたします。また、発熱や風邪症状のある方は、事前にお電話でご相談いただけるとスムーズにご案内が可能です。', 'お知らせ', NULL, NULL, '2025-04-03 00:00:00'),
  ('news-093', '公開', '2025-04-01', 'オンライン診療の導入について', '2024年より、オンライン診療を一部導入いたしました。通院が難しい方や、遠方にお住まいの方にご利用いただけます。ご希望の方は、当院スタッフまでお問い合わせください。', 'お知らせ', NULL, NULL, '2025-04-01 00:00:00'),
  ('news-092', '公開', '2026-01-01', 'テキスト1', 'テキスト1テキスト1テキスト1テキスト1テキスト1テキスト1テキスト1テキスト1テキスト1テキスト1テキスト1テキスト1テキスト1テキスト1テキスト1テキスト1テキスト1テキスト1テキスト1テキスト1テキスト1テキスト1テキスト1テキスト1', '休診情報', NULL, NULL, '2026-01-01 23:59:54'),
